// CrowdRelay decides WHEN to sweep and WHAT is admissible. This reads
// published text and reports what it read. It never judges a candidate and
// never invents a contact.
const e = $json;
if (!e || e.type !== 'crowdrelay.outreach.discovery_requested' || e.version !== 1) return [];
const d = e.data ?? {};
const requested = Number(d.requested_candidates ?? 0);
if (!Number.isInteger(requested) || requested < 1 || requested > 100) {
  throw new Error('Invalid discovery request');
}
const queries = String($env.VIRYA_DISCOVERY_PLAYLIST_QUERIES || '')
  .split('|').map(q => q.trim()).filter(Boolean);
if (queries.length === 0) throw new Error('Set VIRYA_DISCOVERY_PLAYLIST_QUERIES');
const screening = d.screening_contract ?? {};
// One item per search: the credential is attached by n8n, so nothing here
// carries a token.
return queries.map(query => ({ json: {
  event_id: e.id,
  action_id: String(d.action_id || ''),
  requested,
  query,
  min_followers: Number(screening.minimum_follower_count ?? 250)
}}));

// Read a submission route ONLY where a curator published one for that
// purpose. Never infer an address and never pattern-guess one from a name or
// domain: CrowdRelay refuses those as `route_inferred`, and a burned curator
// does not come back. The description snippet travels with every candidate,
// because a route no human can check later is refused as `evidence_missing`.
const plan = $('Validate sweep request').first().json;
const EMAIL = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i;
const URL_RE = /https?:\/\/[^\s"'<>]+/i;
// An address is a submission route only when the surrounding text says so.
const INTENT = /(submi|send|pitch|demo|promo|contact|wy[s\u015b]lij|zg[l\u0142]o[s\u015b]|kontakt)/i;
const SELLS = /(paid\s*(placement|promo)|guaranteed\s*placement|buy\s*a?\s*spot|p[l\u0142]atn[ae]\s*promocj)/i;
const out = [];
for (const item of $input.all()) {
  for (const p of (item.json?.playlists?.items ?? [])) {
    if (!p || p.public === false) continue;
    const description = String(p.description || '').replace(/<[^>]*>/g, ' ').trim();
    if (!description || !INTENT.test(description)) continue;
    const email = description.match(EMAIL)?.[0] ?? null;
    const url = description.match(URL_RE)?.[0] ?? null;
    let route_kind = null, route_value = null;
    if (email) { route_kind = 'email'; route_value = email; }
    else if (url) { route_kind = 'submission_form'; route_value = url; }
    if (!route_value) continue;
    out.push({
      target_kind: 'playlist',
      display_name: String(p.name || '').slice(0, 200),
      source: 'playlist_description',
      source_reference: String(p.external_urls?.spotify || ('spotify:playlist:' + p.id)).slice(0, 2048),
      // Verbatim and bounded: this is what a human re-reads to check us.
      evidence: description.slice(0, 4000),
      route_kind,
      route_value: String(route_value).slice(0, 2048),
      // True only because it was read out of text published for submissions.
      route_is_published: true,
      fit_basis_points: Number($env.VIRYA_DISCOVERY_FIT_BASIS_POINTS || 7000),
      follower_count: Number(p.followers?.total ?? 0) || null,
      engagement_count: null,
      // Raw signals, not verdicts. CrowdRelay screens on these.
      sells_placement: SELLS.test(description),
      churns_indiscriminately: false
    });
  }
}
const seen = new Set();
const unique = out.filter(c => {
  const key = c.route_kind + ':' + c.route_value.toLowerCase();
  if (seen.has(key)) return false;
  seen.add(key); return true;
});
// Always one item, even with nothing found: an empty batch is a real answer
// and the only way CrowdRelay can tell a dry source from a crashed adapter.
//
// `sweep` says what was read, which is the difference between "we looked at two
// hundred playlists and none published a submission route" and "the search
// returned nothing because the credential is dead". Both post zero candidates,
// and only the first is a source worth calling exhausted. Counted from the raw
// responses, before any of the filtering above.
const sources_read = $input.all().length;
let items_seen = 0;
for (const item of $input.all()) {
  items_seen += (item.json?.playlists?.items ?? []).length;
}
const candidates = unique.slice(0, Math.min(plan.requested, 100));
return [{ json: {
  event_id: plan.event_id,
  action_id: plan.action_id,
  candidates,
  // CrowdRelay refuses an incoherent pair, so never report fewer items read
  // than candidates reported.
  sweep: { sources_read, items_seen: Math.max(items_seen, candidates.length) }
}}];
